function serve(req, res, max, control) {
  {
    const chunks = [];
    let size = 0;
    let held = 0;
    let rejected = false;
    const release = () => {
      buffered -= held;
      held = 0;
    };
    req.on('data', (c) => {
      if (rejected) return; // drain and discard the rest so the client can read the answer
      size += c.length;
      if (size > max || buffered + c.length > BUFFERED_BUDGET) {
        rejected = true;
        chunks.length = 0;
        release();
        return;
      }
      chunks.push(c);
      held += c.length;
      buffered += c.length;
    });
    req.on('error', release);
    req.on('close', release);
    req.on('end', () => {
      if (rejected) {
        send(res, tooLarge(max));
        return;
      }
      let url;
